# 找函数结束：从 start 起第一个单独一列的 "\\n}\\n"
end = s.index\('\\n}\\n', start\) + len\('\\n}\\n'\)
old = s[start:end]
assert 'AcceptConnGuarded' in old and 's.wg.Go\(func\(\) {' in old, "函数形态与预期不符"

# 2\) 把 handler 体抽成方法：复用原 s.wg.Go\(func\(\){ ... }\) 内的内容
body_start = old.index\('\\t\\ts.wg.Go\(func\(\) {\\n'\) + len\('\\t\\ts.wg.Go\(func\(\) {\\n'\)
